"""The protocol_to_usdm Excel template: sheet definitions plus workbook read/write.

Design principles
  * One row per entity, entities referenced by *name* (never by USDM id) - ids are generated by the builder.
  * Coded columns take a human decode (e.g. "Phase I/II Trial" or "phase 1/2"); the `Codes` sheet maps
    decodes to C-codes and can be extended per study.
  * Multi-valued cells use ';' as separator.
  * Each Schedule of Activities is a matrix sheet named SoA_<n> (activities down, encounters across).
  * Provenance columns (source_text / method / confidence / review_status) carry extraction evidence so a
    reviewer can accept or fix mappings in a workbench.

The intermediate in-memory form ("StudyData") is a plain dict:
    {"Study": {key: value}, "Population": {key: value}, "<ListSheet>": [ {col: value} ], "SoA": [timeline dicts]}
"""
from __future__ import annotations

from openpyxl import Workbook, load_workbook
from openpyxl.styles import Alignment, Font, PatternFill
from openpyxl.utils import get_column_letter
from openpyxl.worksheet.datavalidation import DataValidation

# ---------------------------------------------------------------------------------------------- spec
KV_SHEETS = {
    "Study": [
        ("name", "Study name (short, unique)", None),
        ("label", "Study label", None),
        ("description", "Study description", None),
        ("version", "Protocol / study version identifier", None),
        ("version_rationale", "Rationale for this version (e.g. 'Amendment 2')", None),
        ("approval_date", "Sponsor approval date (YYYY-MM-DD)", None),
        ("sponsor", "Sponsor organisation name (must exist on Organizations)", None),
        ("study_type", "Interventional / Observational", "study_type"),
        ("phase", "Trial phase", "phase"),
        ("blinding", "Blinding schema", "blinding"),
        ("model", "Intervention model", "model"),
        ("characteristics", "Design characteristics (;)", "characteristic"),
        ("sub_types", "Study sub-types (;)", "sub_type"),
        ("therapeutic_areas", "Business therapeutic areas (free text ;)", None),
        ("design_name", "Study design name", None),
        ("design_description", "Study design description", None),
        ("design_rationale", "Study design rationale", None),
        ("document_name", "Protocol document name", None),
        ("document_version", "Protocol document version", None),
        ("document_status", "Final / Draft", "document_status"),
        ("document_template", "Template name (e.g. Sponsor, ICH M11)", None),
        ("language", "ISO 639-1 language code", None),
    ],
    "Population": [
        ("name", "Population name", None),
        ("label", "Label", None),
        ("description", "Description", None),
        ("healthy", "Includes healthy subjects (Y/N)", None),
        ("min_age", "Minimum age", None),
        ("max_age", "Maximum age", None),
        ("age_unit", "Age unit", "unit"),
        ("planned_enrollment", "Planned enrolment number", None),
        ("planned_completion", "Planned completion number", None),
        ("sex", "Planned sex (;)", "sex"),
    ],
}

LIST_SHEETS = {
    "Titles": [("type", "title_type"), ("text", None)],
    "Organizations": [("name", None), ("label", None), ("type", "organization_type"), ("identifier_scheme", None), ("identifier", None)],
    "Identifiers": [("text", None), ("organization", None)],
    "Cohorts": [("name", None), ("label", None), ("description", None), ("healthy", None), ("min_age", None),
                ("max_age", None), ("age_unit", "unit"), ("planned_enrollment", None), ("sex", "sex")],
    "Arms": [("name", None), ("label", None), ("description", None), ("type", "arm_type"),
             ("data_origin_type", "data_origin_type"), ("data_origin_description", None), ("cohorts", None)],
    "Epochs": [("name", None), ("label", None), ("description", None), ("type", "epoch_type")],
    "Elements": [("name", None), ("label", None), ("description", None), ("interventions", None),
                 ("start_rule", None), ("end_rule", None)],
    "Cells": [("arm", None), ("epoch", None), ("elements", None)],
    "Products": [("name", None), ("label", None), ("description", None), ("dose_form", "dose_form"),
                 ("designation", "product_designation"), ("sourcing", "sourcing")],
    "Interventions": [("name", None), ("label", None), ("description", None), ("role", "intervention_role"),
                      ("type", "intervention_type")],
    "Administrations": [("intervention", None), ("name", None), ("label", None), ("description", None),
                        ("dose_value", None), ("dose_unit", "unit"), ("route", "route"), ("frequency", "frequency"),
                        ("product", None), ("duration_text", None)],
    "Objectives": [("name", None), ("label", None), ("level", "objective_level"), ("text", None), ("description", None)],
    "Endpoints": [("objective", None), ("name", None), ("label", None), ("level", "endpoint_level"),
                  ("purpose", None), ("text", None), ("description", None)],
    "Eligibility": [("identifier", None), ("category", "criterion_category"), ("name", None), ("label", None), ("text", None)],
    "AnalysisPopulations": [("name", None), ("label", None), ("text", None)],
    "Encounters": [("name", None), ("label", None), ("description", None), ("type", "encounter_type"),
                   ("setting", "environmental_setting"), ("contact_mode", "contact_mode")],
    "Timelines": [("name", None), ("label", None), ("description", None), ("main", None), ("entry_condition", None),
                  ("sheet", None), ("planned_duration_text", None), ("planned_duration_value", None),
                  ("planned_duration_unit", "unit"), ("triggered_by_activity", None)],
    "Activities": [("name", None), ("label", None), ("description", None), ("bc_category", None),
                   ("biomedical_concepts", None), ("surrogates", None), ("source_text", None), ("method", None),
                   ("confidence", None), ("review_status", None)],
    "BiomedicalConcepts": [("name", None), ("label", None), ("ncit_code", None), ("reference", None), ("synonyms", None),
                           ("category", None), ("source", None), ("method", None), ("confidence", None),
                           ("evidence", None), ("review_status", None)],
    "BCSurrogates": [("name", None), ("label", None), ("description", None), ("reference", None), ("evidence", None),
                     ("review_status", None)],
    "BCCategories": [("name", None), ("label", None), ("description", None)],
    "Conditions": [("name", None), ("timeline", None), ("marker", None), ("label", None), ("text", None), ("applies_to", None)],
    "Abbreviations": [("abbreviation", None), ("expansion", None)],
    "Narrative": [("section_number", None), ("section_title", None), ("text", None)],
    "Codes": [("field", None), ("decode", None), ("code", None), ("code_system", None),
              ("code_system_version", None), ("synonyms", None)],
}

SOA_HEADER_ROWS = ["Epoch", "Encounter", "Day", "Window -", "Window +", "Label", "Notes"]
SOA_FIRST_ROW = 4  # rows 1-2: Timeline / Description; header block starts at row 4

README = [
    "protocol_to_usdm Excel template (USDM v4)",
    "",
    "Fill one row per entity; refer to other entities by their 'name'. Multi-valued cells use ';'.",
    "Coded columns accept the decode or a synonym (see the Codes sheet; add rows there for new terms).",
    "Schedules of Activities: one SoA_<n> sheet per timeline (listed on Timelines.sheet).",
    "  Rows 4-10 hold Epoch / Encounter / Day / Window - / Window + / Label / Notes.",
    "    Day = nominal study day (Day 1 = anchor, no Day 0) or a clock offset such as -1h, 0h, 30m (0h = anchor).",
    "    Windows are in days, or e.g. 5m / 1h. Notes = footnote markers that apply to the whole visit column.",
    "  From row 12: column A = activity name (as on Activities), then 'X' where the activity occurs.",
    "  Characters after X (e.g. 'X†', 'Xl') are footnote markers, resolved against Conditions.marker",
    "    (Conditions.timeline scopes a marker to one timeline; blank = all timelines).",
    "Activities.biomedical_concepts lists BC names from BiomedicalConcepts; surrogates from BCSurrogates.",
    "Provenance columns (source_text, method, confidence, evidence, review_status) are carried into",
    "  extensionAttributes so a workbench can show why a mapping was made.",
    "Build JSON:  python -m protocol_to_usdm build <workbook.xlsx> <out.json>",
]

HDR_FILL = PatternFill("solid", fgColor="1F4E78")
HDR_FONT = Font(bold=True, color="FFFFFF")
KEY_FILL = PatternFill("solid", fgColor="DDEBF7")


# ---------------------------------------------------------------------------------------------- write
def _fmt(v):
    if isinstance(v, (list, tuple)):
        return "; ".join(str(x) for x in v if x not in (None, ""))
    if isinstance(v, bool):
        return "Y" if v else "N"
    return v


def write_workbook(data: dict, path: str, ct=None):
    wb = Workbook()
    ws = wb.active
    ws.title = "README"
    for i, line in enumerate(README, 1):
        ws.cell(i, 1, line).font = Font(bold=(i == 1), size=12 if i == 1 else 11)
    ws.column_dimensions["A"].width = 110

    lists_sheet = wb.create_sheet("_lists")  # CT decodes for dropdowns
    lists_sheet.sheet_state = "hidden"
    list_ranges = {}
    if ct is not None:
        fields = sorted({f for s in KV_SHEETS.values() for _, _, f in s if f} |
                        {f for s in LIST_SHEETS.values() for _, f in s if f})
        for ci, field in enumerate(fields, 1):
            decs = ct.decodes(field)
            lists_sheet.cell(1, ci, field)
            for ri, d in enumerate(decs, 2):
                lists_sheet.cell(ri, ci, d)
            col = get_column_letter(ci)
            list_ranges[field] = f"_lists!${col}$2:${col}${max(2, len(decs) + 1)}"

    for sheet, keys in KV_SHEETS.items():
        ws = wb.create_sheet(sheet)
        ws.append(["key", "value", "help"])
        vals = data.get(sheet, {}) or {}
        for key, help_, field in keys:
            ws.append([key, _fmt(vals.get(key)), help_ + (f"  [CT: {field}]" if field else "")])
        for c in ws[1]:
            c.fill, c.font = HDR_FILL, HDR_FONT
        for r in range(2, ws.max_row + 1):
            ws.cell(r, 1).fill = KEY_FILL
            ws.cell(r, 2).alignment = Alignment(wrap_text=True, vertical="top")
        ws.column_dimensions["A"].width, ws.column_dimensions["B"].width, ws.column_dimensions["C"].width = 22, 80, 60

    for sheet, cols in LIST_SHEETS.items():
        ws = wb.create_sheet(sheet)
        ws.append([c for c, _ in cols])
        for c in ws[1]:
            c.fill, c.font = HDR_FILL, HDR_FONT
        rows = data.get(sheet, []) or []
        if sheet == "Codes" and not rows and ct is not None:
            rows = [{"field": f, "decode": e[1], "code": e[0], "code_system": e[2], "code_system_version": e[3]}
                    for f, t in sorted(ct.table.items()) for e in sorted(set(t.values()))]
        for r in rows:
            ws.append([_fmt(r.get(c)) for c, _ in cols])
        for ci, (c, field) in enumerate(cols, 1):
            width = 60 if c in ("text", "description", "source_text", "evidence") else 26
            ws.column_dimensions[get_column_letter(ci)].width = width
            if field and field in list_ranges and c not in ("sex",):
                dv = DataValidation(type="list", formula1=list_ranges[field], allow_blank=True, showErrorMessage=False)
                ws.add_data_validation(dv)
                dv.add(f"{get_column_letter(ci)}2:{get_column_letter(ci)}500")
        for row in ws.iter_rows(min_row=2):
            for c in row:
                c.alignment = Alignment(wrap_text=True, vertical="top")
        ws.freeze_panes = "A2"

    for i, tl in enumerate(data.get("SoA", []) or [], 1):
        _write_soa(wb, tl.get("sheet") or f"SoA_{i}", tl)
    if not data.get("SoA"):
        _write_soa(wb, "SoA_1", {"timeline": "", "columns": [], "rows": []})
    wb.save(path)


def _write_soa(wb, name, tl):
    ws = wb.create_sheet(name[:31])
    ws["A1"], ws["B1"] = "Timeline", tl.get("timeline")
    ws["A2"], ws["B2"] = "Description", tl.get("description")
    ws["A1"].font = ws["A2"].font = Font(bold=True)
    keys = ["epoch", "encounter", "day", "window_lower", "window_upper", "label", "notes"]
    for ri, (hdr, k) in enumerate(zip(SOA_HEADER_ROWS, keys)):
        r = SOA_FIRST_ROW + ri
        ws.cell(r, 1, hdr).fill = KEY_FILL
        ws.cell(r, 1).font = Font(bold=True)
        for ci, col in enumerate(tl.get("columns", []), 2):
            c = ws.cell(r, ci, col.get(k))
            c.fill, c.font = HDR_FILL, HDR_FONT
            c.alignment = Alignment(horizontal="center", wrap_text=True)
    start = SOA_FIRST_ROW + len(SOA_HEADER_ROWS)
    ws.cell(start, 1, "Activity").font = Font(bold=True)
    for ri, row in enumerate(tl.get("rows", []), start + 1):
        ws.cell(ri, 1, row["activity"])
        for ci, v in enumerate(row.get("cells", []), 2):
            if v:
                ws.cell(ri, ci, v).alignment = Alignment(horizontal="center")
    ws.column_dimensions["A"].width = 48
    for ci in range(2, len(tl.get("columns", [])) + 2):
        ws.column_dimensions[get_column_letter(ci)].width = 16
    ws.freeze_panes = ws.cell(start + 1, 2)


# ---------------------------------------------------------------------------------------------- read
def _clean(v):
    if v is None:
        return None
    if isinstance(v, str):
        v = v.strip()
        return v or None
    return v


def read_workbook(path: str) -> dict:
    wb = load_workbook(path, data_only=True)  # path or binary file object
    try:
        return _read(wb)
    finally:
        wb.close()


def _read(wb) -> dict:
    data: dict = {}
    for sheet in KV_SHEETS:
        kv = {}
        if sheet in wb.sheetnames:
            for row in wb[sheet].iter_rows(min_row=2, values_only=True):
                if row and row[0]:
                    kv[str(row[0]).strip()] = _clean(row[1] if len(row) > 1 else None)
        data[sheet] = kv
    for sheet in LIST_SHEETS:
        rows = []
        if sheet in wb.sheetnames:
            it = wb[sheet].iter_rows(values_only=True)
            hdr = [str(h).strip() if h else None for h in next(it, [])]
            for row in it:
                rec = {h: _clean(v) for h, v in zip(hdr, row) if h}
                if any(v is not None for v in rec.values()):
                    rows.append(rec)
        data[sheet] = rows
    soa_sheets = [s for s in wb.sheetnames if s.startswith("SoA")]
    data["SoA"] = [_read_soa(wb[s]) for s in soa_sheets]
    data["SoA"] = [t for t in data["SoA"] if t["timeline"]]
    return data


def _read_soa(ws) -> dict:
    tl = {"sheet": ws.title, "timeline": _clean(ws["B1"].value), "description": _clean(ws["B2"].value),
          "columns": [], "rows": []}
    keys = ["epoch", "encounter", "day", "window_lower", "window_upper", "label", "notes"]
    ncol = 0
    for ci in range(2, ws.max_column + 1):
        if any(_clean(ws.cell(SOA_FIRST_ROW + i, ci).value) is not None for i in range(len(SOA_HEADER_ROWS))):
            ncol = ci - 1
    for ci in range(2, ncol + 2):
        tl["columns"].append({k: _clean(ws.cell(SOA_FIRST_ROW + i, ci).value) for i, k in enumerate(keys)})
    start = SOA_FIRST_ROW + len(SOA_HEADER_ROWS) + 1
    for r in range(start, ws.max_row + 1):
        act = _clean(ws.cell(r, 1).value)
        if not act:
            continue
        cells = [_clean(ws.cell(r, ci).value) for ci in range(2, ncol + 2)]
        tl["rows"].append({"activity": act, "cells": [str(c) if c is not None else None for c in cells]})
    return tl
